item(d,22,'RED và USE nhìn hệ thống từ hai góc nào?', ['RED theo requests; USE theo tài nguyên và saturation','RED theo tài nguyên; USE chỉ theo chất lượng final answer','Cả hai chỉ đo CPU/RAM, không đo request latency'],'a','RED gồm rate/errors/duration; USE gồm utilization/saturation/errors của resource.')
item(d,23,'Vì sao latency trung bình có thể che trải nghiệm xấu của một nhóm người dùng?', ['Một số request ở long tail có thể rất chậm dù average vẫn thấp','Average luôn bằng P95 nên không cần percentile','Average chỉ đo token đầu tiên nên bỏ qua total duration'],'a','Percentiles thể hiện phần đuôi phân bố mà một số trung bình có thể làm mờ.')
item(d,23,'TTFT đo khoảng thời gian nào?', ['Từ khi gửi request đến token đầu tiên','Từ token đầu đến token cuối','Trung bình khoảng cách giữa các output tokens'],'a','TTFT phản ánh thời điểm người dùng bắt đầu thấy phản hồi, khác inter-token và tổng latency.')
item(d,26,'Vì sao nên phối hợp heuristic, judge, user signal và outcome trong quality monitoring?', ['Các tầng có cost/độ trễ/độ gần business value khác nhau và bổ sung nhau','Heuristic đúng format là đủ thay toàn bộ task success và user outcome','Outcome đến chậm nên không có ích để kiểm chứng xu hướng quality'],'a','Kiểm tự động rẻ giúp phát hiện sớm; feedback/outcome xác nhận tác động thực tế.')
item(d,29,'Những metric nào trực tiếp hỗ trợ chẩn đoán hành vi gọi tool? (Chọn tất cả đáp án đúng.)',['Schema-fail/timeout rate','Loop rate và argument hallucination','Chỉ latency tổng của endpoint','Chỉ số lượng documents trong corpus'],['a','b'],'Tool failures cần được đo ở selection/args/execution/repetition, không chỉ endpoint health.',kind='multiple_choice')
item(d,30,'Vì sao error taxonomy hữu ích hơn chỉ ghi error rate tổng?', ['Giúp phân biệt provider timeout, tool schema, guardrail block hoặc context overflow để chọn owner/cách xử lý','Mọi loại lỗi đều nên dùng cùng một retry policy','Error rate thấp tự bảo đảm không có một loại lỗi nghiêm trọng tập trung ở một flow'],'a','Một tỷ lệ tổng không nói lỗi nằm ở dependency nào hay cần fallback/re-prompt/giảm context.')
item(d,31,'Policy đổi làm cùng một input nay cần output khác đang thể hiện loại drift nào?', ['Concept drift','Data drift chỉ do user dùng cách diễn đạt mới','Model drift chỉ do provider thay model snapshot'],'a','Concept drift là mapping input→output thay đổi; khác distribution đầu vào hoặc behavior model.')
item(d,35,'Những trường nào giúp điều tra một LLM call mà không phải log raw prompt nhạy cảm? (Chọn tất cả đáp án đúng.)',['Prompt template ID và model/version','Token counts, latency, finish reason và sanitized tool results','API key đầy đủ để đối chiếu tài khoản','Raw prompt chứa PII để tránh cần correlation ID'],['a','b'],'Telemetry cấu trúc giữ thông tin vận hành nhưng giảm dữ liệu bí mật không cần thiết.',kind='multiple_choice')
item(d,38,'Fallback đã được dùng nhưng request vẫn hoàn thành ở trạng thái degraded thường phù hợp log level nào hơn một fatal failure?', ['WARN','DEBUG như thông tin chỉ dùng trong dev','ERROR dù đã có fallback thành công và không còn lỗi cần can thiệp'],'a','WARN diễn tả suy giảm nhưng còn chạy; ERROR dành cho thất bại cần chú ý.')
item(d,39,'Correlation ID giải quyết nhu cầu nào khi request đi qua nhiều service?', ['Nối các log entries của cùng một request','Xác định hai user có cùng preference hay không','Thay model version để xác định prompt nào được dùng'],'a','Một ID xuyên service giúp đi từ sự kiện đầu vào đến response và làm cầu nối với tracing.')
item(d,41,'Head sampling và tail sampling khác nhau ở thời điểm quyết định giữ trace thế nào?', ['Head quyết định lúc đầu; tail đợi kết thúc để chọn theo lỗi/outlier','Head chỉ giữ error sau khi xong; tail quyết định ngẫu nhiên trước khi chạy','Cả hai luôn giữ đúng cùng traces bất kể kết quả thực thi'],'a','Tail có thêm kết quả để giữ errors/slow runs nhưng chi phí thu thập/quản lý cao hơn.')
item(d,43,'Audit log khác app log chủ yếu ở mục đích và tính toàn vẹn nào?', ['Ghi ai làm gì khi nào, append-only và truy cập hạn chế','Ưu tiên debug text tùy sửa/xóa để giảm volume','Chỉ chứa latency tổng, không cần danh tính hay hành động'],'a','Audit phục vụ accountability/forensics; không được xử lý như log debug có thể sample tùy ý.')
item(d,45,'Một trace và các spans có quan hệ nào?', ['Trace bao gồm các spans của một request, có quan hệ cha–con giữa các bước','Mỗi span luôn là một request độc lập không thể liên kết','Trace chỉ là total latency, không có thời gian từng bước'],'a','Span tree thể hiện cấu trúc và thời gian để tìm bottleneck trong hành trình request.')
item(d,47,'Instrumentation bằng OpenTelemetry giúp giảm vendor lock-in theo cách nào?', ['Sinh/xuất telemetry theo chuẩn để gửi đến nhiều backend','Mã ứng dụng chỉ có thể gửi tới một dashboard độc quyền','Đổi storage backend luôn phải viết lại mọi log statement'],'a','OTel tách lớp thu telemetry khỏi backend lưu/hiển thị, có thể xuất nhiều đích.')
item(d,56,'Triệu chứng nào thích hợp để page hơn một chỉ số nguyên nhân chưa ảnh hưởng người dùng?', ['Error rate hoặc latency user-facing vượt ngưỡng','Cache miss cao nhưng service vẫn đáp ứng SLO','CPU tăng trong một batch nền không ảnh hưởng request'],'a','Paging nên gắn tác động mà user cảm nhận; resource metrics hỗ trợ chẩn đoán nguyên nhân.')
item(d,59,'Một alert đủ hành động được cần nối current value/severity/impact với thông tin nào?', ['Dashboard/trace đã lọc, runbook và on-call owner','Chỉ tên metric để người trực tự tìm mọi ngữ cảnh','Chỉ threshold, không cần trạng thái hiện tại hoặc nơi xử lý'],'a','Alert phải giúp người trực hiểu tác động và bước xử lý ngay, không chỉ báo có số bất thường.')
item(d,74,'Những biện pháp nào giảm PII leakage trong logs/traces ngay từ nguồn? (Chọn tất cả đáp án đúng.)',['Mask/redact và allowlist fields cần log','Dùng template ID thay raw sensitive prompt','Hash định danh khi không cần giữ bản gốc','Capture mọi content rồi chỉ hạn chế quyền dashboard'],['a','b','c'],'Không thu dữ liệu không cần thiết giảm bề mặt rủi ro và gánh nặng retention/deletion.',kind='multiple_choice')
d='p1-d14'
item(d,20,'Partial credit và weighted scoring khác binary completion ở điểm nào?', ['Cho biết phần việc đạt được và mức quan trọng từng bước, thay vì chỉ pass/fail toàn task','Chỉ đổi nhãn pass thành một con số nhưng không xét subtasks','Tự bảo đảm một agent hoàn thành task khi nó làm nhiều bước hơn'],'a','Binary đơn giản nhưng mất thông tin; partial/weighted mô tả tiến độ và tầm quan trọng.')
item(d,21,'Với câu trả lời open-ended nhiều cách diễn đạt đúng, vì sao exact match thường chưa đủ?', ['Khác câu chữ có thể vẫn tương đương nghĩa, cần phương pháp đánh giá nuance phù hợp','Exact match luôn nhận ra mọi paraphrase có nghĩa tương đương','LLM judge không cần calibration vì thay được mọi expert'],'a','Exact match phù hợp câu ngắn/factual hoặc sanity check; nuance cần judge/human được calibrate.')
item(d,27,'Những yếu tố nào làm golden dataset đáng tin cậy hơn? (Chọn tất cả đáp án đúng.)',['Expected answers được expert review','Bao phủ use cases và độ khó khác nhau','Có edge/adversarial cases','Chỉ gồm các query demo dễ nhất đã pass'],['a','b','c'],'Nhãn đúng và phạm vi đại diện quyết định evaluation có phản ánh hệ thống thực hay không.',kind='multiple_choice')
item(d,28,'LLM-generated QA pairs thích hợp cho bootstrapping với điều kiện nào?', ['Human filter/fix và bổ sung cases thực/giá trị cao','Giữ nguyên mọi generated label để tránh human bias','Chỉ dùng data tổng hợp rồi bỏ production failures vì khó chuẩn hóa'],'a','Sinh nhanh tạo nền ban đầu nhưng cần chỉnh nhãn/phạm vi bằng domain judgment và dữ liệu thực.')
item(d,31,'Cohen’s kappa bổ sung gì so với tỷ lệ agreement quan sát thuần túy?', ['Điều chỉnh agreement kỳ vọng do ngẫu nhiên','Chỉ đo output nào có độ dài giống nhau','Chỉ tính accuracy của model so với một labeler duy nhất'],'a','Kappa phân biệt agreement thực với mức có thể xuất hiện bởi chance, giúp đánh giá rubric/label consistency.')
item(d,32,'Stratified sampling giúp benchmark đại diện hơn bằng cách nào?', ['Giữ samples cho từng use case, difficulty và user type thay vì chỉ lấy case dễ phổ biến','Chỉ lấy use case có traffic lớn nhất rồi bỏ mọi nhóm còn lại','Chỉ tăng tổng số sample mà không xét composition'],'a','Cấu trúc sample cần phản ánh các lát cắt và edge cases, không chỉ số lượng tổng.')
item(d,38,'Reference-based và reference-free evaluation khác nhau ở căn cứ chấm nào?', ['Reference-based so với đáp án chuẩn; reference-free xét rubric khi không có reference chắc chắn','Reference-free không cần tiêu chí nào, chỉ cần model thích answer','Reference-based chỉ chấm format còn reference-free mới được chấm nội dung'],'a','Cả hai cần tiêu chí rõ; có hay không ground truth quyết định cách dùng và calibration.')
item(d,39,'Trong pairwise judging, đổi thứ tự A/B giúp kiểm soát bias nào?', ['Position bias','Chỉ model knowledge cutoff','Chỉ việc ground-truth label bị thiếu'],'a','Judge có thể ưu tiên vị trí xuất hiện, nên swap/randomize giúp phát hiện thiên lệch thứ tự.')
item(d,41,'Judge thường cho answer dài điểm cao hơn dù không thêm thông tin. Cách giảm verbosity bias nào phù hợp?', ['Rubric chấp nhận câu ngắn đúng và đo length riêng','Bổ sung yêu cầu answer phải dài hơn baseline','Coi độ dài là bằng chứng correctness trong mọi domain'],'a','Tách độ dài khỏi quality tránh việc văn bản dài nhận lợi thế không xứng đáng.')
item(d,42,'Vì sao binary judge theo từng failure mode hữu ích cho CI gate hơn một điểm tổng mơ hồ?', ['FAIL gắn lỗi cụ thể dẫn tới hành động sửa rõ, giảm ranh giới điểm chủ quan','Một điểm tổng luôn xác định được chính xác module và lỗi cần sửa','Binary cho phép bỏ critique và bỏ kiểm tra nhãn người'],'a','Các verdict riêng như hallucination/policy/relevance chuyển thành tỷ lệ lỗi có thể chẩn đoán.')
item(d,43,'Trước khi dùng LLM judge làm tín hiệu chất lượng, calibration cần đối chiếu với gì?', ['Human labels trên cùng tập outputs và rubric','Một tập answer khác do cùng judge tự sinh và tự chấm','Chỉ giá/token của judge để suy ra độ chính xác'],'a','Cùng outputs, rubric và nhãn người giúp đo mức agreement/lỗi của judge trước khi dựa vào nó.')
item(d,53,'Chạy5 lần trên cùng20items không tạo100 mẫu độc lập vì sao?', ['Các run trên cùng item tương quan; item khó vẫn khó qua nhiều lần','Mỗi run luôn có output giống hệt nên chỉ có một sample','Số run nhiều tự động tăng số dạng nhiệm vụ được bao phủ'],'a','Lặp giúp giảm noise trong item nhưng không thay việc có thêm item độc lập.')
item(d,55,'So sánh hai version bằng paired difference theo cùng item giúp điều gì?', ['Kiểm soát độ khó item chung, thường giảm phương sai của hiệu số','Biến các run lặp trên một item thành các item độc lập','Tự tăng mức significance chỉ bằng tăng n mà không chọn alpha'],'a','Ghép cùng item tách bớt chênh lệch do composition/độ khó, cần báo uncertainty của hiệu số.')
item(d,59,'Vì sao gate outcome không nên ép agent phải đi đúng một trajectory mẫu?', ['Có thể tồn tại một đường khác vẫn đạt kết quả đúng; trace hữu ích riêng để chẩn đoán','Mọi trajectory khác nhau đều dẫn tới outcome khác nhau','Chỉ kiểm từng tool name là đủ bỏ qua kết quả task'],'a','Chấm outcome phân biệt mục tiêu đạt được với một cách giải duy nhất, còn trace giúp hiểu hành vi.')
item(d,62,'pass@k và pass^k khác nhau ở sự kiện thành công nào?', ['pass@k: ít nhất một lần; pass^k: cả k lần đều thành công','pass@k: cả k lần; pass^k: ít nhất một lần','Cả hai chỉ đo lần chạy tốt nhất và luôn tăng cùng nhau theo k'],'a','Một metric biểu thị capability có thể làm được, metric kia nhấn mạnh độ tin cậy lặp lại.')
item(d,74,'Failure clustering nên ưu tiên sửa theo tiêu chí nào?', ['Nhóm root cause có nhiều failure và impact cao','Sửa ngẫu nhiên từng output riêng để tăng số ticket đã đóng','Chỉ sửa case có wording dễ thay nhất trong prompt'],'a','Sửa một nguyên nhân chung có thể giải nhiều triệu chứng; taxonomy rồi cluster tạo đòn bẩy cải thiện.')
