item(d,9,'Hệ thống có ràng buộc dữ liệu không ra mạng ngoài và chỉ được chạy trong mạng air-gapped. Quyết định deploy cần ưu tiên gì?', ['Kiến trúc đáp ứng ràng buộc residency/network, có thể cần on-premise','Đẩy mọi request lên cloud API vì triển khai nhanh hơn','Chỉ đổi giao diện rồi giữ nguyên đường truyền dữ liệu ra ngoài'],'a','Ràng buộc enterprise có thể quyết định nơi chạy, trước lựa chọn tiện lợi của platform.',kind='scenario',context='Đây là yêu cầu thiết kế đã được chủ hệ thống xác nhận cho workload.')
item(d,10,'Hybrid deployment có thể phân tách sensitive và non-sensitive workloads thế nào?', ['Giữ dữ liệu nhạy cảm ở on-prem, route phần phù hợp sang cloud API','Gửi mọi dữ liệu lên cloud rồi xóa bản local để tăng control','Giữ toàn bộ workload on-prem nhưng gọi đó là hybrid chỉ vì có browser UI'],'a','Hybrid kết hợp vị trí xử lý theo tính chất dữ liệu, trade-off control và khả năng triển khai.')
item(d,13,'Những khoản nào ngoài API tokens cần được đưa vào cost anatomy của hệ thống AI? (Chọn tất cả đáp án đúng.)',['Compute và storage/vector DB','Human review và vận hành monitoring','Chỉ chi phí token là đủ khi endpoint đã deploy','Review được xem là miễn phí vì có người dùng thực hiện'],['a','b'],'Một hệ thống phải trả cả hạ tầng, con người và vận hành, không chỉ hóa đơn LLM.')
item(d,14,'Budget chỉ nhân giá token với traffic có thể thiếu những phần nào? (Chọn tất cả đáp án đúng.)',['Retry overhead và các LLM calls của guardrails','Monitoring và eval pipeline','Chỉ cần cộng thêm tên provider vào estimate','Chỉ giảm output length là đã tính đủ hidden cost'],['a','b'],'Các đường phụ và vòng kiểm soát cũng tiêu compute/LLM/human effort nên cần tính tổng.')
item(d,15,'Vì sao nên nâng deployment tier theo traffic thực thay vì tối ưu quy mô lớn ngay từ MVP?', ['Tránh đầu tư độ phức tạp/cost trước khi nhu cầu chứng minh cần thiết','Stack đắt hơn luôn tạo user value cao hơn','MVP không cần đo traffic vì chỉ có giai đoạn Scale mới có người dùng'],'a','Khởi đầu theo nhu cầu nhỏ rồi tăng mức đầu tư khi tải và yêu cầu thực đòi hỏi.')
item(d,17,'Semantic caching giảm chi phí trong workload nào trực tiếp nhất?', ['Nhiều câu hỏi gần nghĩa có thể tái dùng response phù hợp','Mỗi request có dữ liệu độc nhất thay đổi liên tục và không thể tái sử dụng','Mọi action ghi tiền cần được thực thi lại dù intent đã có kết quả'],'a','Cache response theo similarity hữu ích khi query lặp nghĩa, nhưng phải xét tính còn hiệu lực.')
item(d,17,'Prompt compression tối ưu khoản nào bằng cơ chế nào?', ['Giảm input tokens bằng cách giữ ý cần thiết trong context ngắn hơn','Giảm output cost bằng cách không thu thập evidence','Thay mọi context bằng câu trả lời cũ từ semantic cache'],'a','Compression rút ngắn context trước call, khác routing model hoặc tái dùng response.')
item(d,18,'Model routing cân bằng cost/quality bằng cách nào?', ['Phân loại độ khó, đưa simple task tới model rẻ và complex task tới model mạnh','Chọn cùng model mạnh nhất cho mọi query để coi cost là cố định','Chọn model rẻ cho mọi task rồi bỏ kiểm tra quality khi task khó'],'a','Routing dùng độ khó/use case để dành năng lực đắt hơn cho nơi tạo giá trị.')
item(d,20,'Queue-based processing giúp xử lý traffic spike theo cơ chế nào?', ['Buffer công việc và xử lý có điều phối thay vì làm mọi request timeout','Tự tăng tốc model bằng cách xóa mọi request còn chờ','Cho mọi request chạy đồng thời không giới hạn dependency capacity'],'a','Queue làm mượt tải, cho người dùng trạng thái đang xử lý khi công việc chưa xong.')
item(d,20,'Khi LLM provider gặp outage, circuit breaker/fallback nhằm đạt mục tiêu nào?', ['Ngừng gọi dependency lỗi và giữ trải nghiệm suy giảm có kiểm soát','Tăng retry tới provider lỗi mà không giới hạn để đạt success','Giữ trạng thái closed bất kể error rate để tránh thay đường xử lý'],'a','Breaker hạn chế cascading load và dùng cache/message/provider khác theo policy.')
item(d,20,'Horizontal scaling của agent cần điều kiện trạng thái nào để nhiều instance phối hợp?', ['Stateless compute với state được externalize phù hợp','Mọi session chỉ nằm trong RAM instance và mất khi route sang instance khác','Mỗi instance tự giữ một bản state không đồng bộ nhưng vẫn xử lý cùng session'],'a','Nhiều instance cần truy cập state nhất quán thay vì phụ thuộc một process cụ thể.')
item(d,22,'Một nhóm đang thiếu PRD, risk assessment và ROI model cần tăng cường năng lực nào trước?', ['Business/product judgment','Chỉ inference-kernel optimization','Chỉ model alignment training'],'a','Định nghĩa giá trị, requirement, risk và economics là nhóm năng lực business, khác infra hay model mechanics.')
item(d,28,'AI exposure cao của một nghề cho phép kết luận chắc chắn nào về mất việc?', ['Không thể đồng nhất với mất việc; exposure nói nhiệm vụ có thể được AI hỗ trợ/thực hiện','Exposure chính là tỷ lệ lao động đã mất việc thực tế','Exposure tự chứng minh mọi nhiệm vụ sẽ được tự động hóa hoàn toàn'],'a','Khả năng tác động nhiệm vụ khác automation thực tế và khác net employment change.')
item(d,36,'Khi AI hỗ trợ nhiều phần viết code, những kỹ năng nào vẫn quan trọng để chịu trách nhiệm sản phẩm? (Chọn tất cả đáp án đúng.)',['Kiểm soát chất lượng output và tư duy phản biện','Thu thập yêu cầu, thiết kế hệ thống và giao tiếp liên chức năng','Chỉ tăng tốc gõ code, bỏ việc kiểm chứng kết quả','Chỉ biết gọi tool là đủ thay mọi phán đoán bối cảnh'],['a','b'],'Tự động hóa một phần execution không thay việc định nghĩa đúng, kiểm chứng và phối hợp giải pháp.')
item(d,42,'Lựa chọn hướng chuyên môn cá nhân nên kết hợp những trục nào thay vì chỉ nhìn một dự báo tăng trưởng?', ['Cơ hội, rào cản gia nhập, sở thích và mức sẵn sàng năng lực','Chỉ chức danh có tốc độ tăng trưởng cao nhất','Chỉ chọn mảng có demo dễ làm nhất bất kể sở thích/nền tảng'],'a','Fit cá nhân nằm ở giao điểm thị trường, năng lực và động lực, không có hướng tuyệt đối đúng cho mọi người.')
item(d,45,'Bộ deliverable nào thể hiện trọng tâm AI infrastructure/data rõ nhất?', ['Production data pipeline, self-hosted serving, CI/CD và monitoring','Business plan, pricing và go-to-market strategy','Bộ user interviews và brand positioning không có hạ tầng vận hành'],'a','Infrastructure tập trung đường dữ liệu, serving và vận hành đáng tin cậy, khác product strategy.')
item(d,46,'Nhu cầu phát triển agent có memory dài hạn, GraphRAG và fine-tuning thuộc trọng tâm kỹ thuật nào?', ['AI application/agent engineering','Chỉ financial modeling và market sizing','Chỉ quản lý quota GPU, không cần logic ứng dụng'],'a','Đây là các năng lực xây hành vi và tri thức của ứng dụng agent, bổ sung cho nền hạ tầng.')
